def substring_beauty_sum(s):
 answer=0
 for left in range(len(s)):
  counts={}
  for right in range(left,len(s)):
   counts[s[right]]=counts.get(s[right],0)+1;values=counts.values();answer+=max(values)-min(values)
 return answer

